package com.codepilot1c.core.tools.development;
import java.util.concurrent.CompletableFuture;
import com.google.gson.Gson;
import com.codepilot1c.core.tools.*;
import com.codepilot1c.core.edt.development.RuntimeFormService;
@ToolMeta(name="edt_form_action",category="qa",mutating=true,tags={"workspace","edt","sensitive"})
public final class EdtFormActionTool extends AbstractTool {
 public String getDescription(){return "Default transport=vanessa. transport=testclient uses an owned client_id and snapshot_id with exact expected_window; supports open/close/input/command/batch (up to16 steps, each with expected_window and optional expected_form/expect). open accepts only in-base navigation_link. A completed direct idempotency key returns its durable terminal result immediately. Direct batch is not a transaction, stops on first failed/unknown result, never replays a claimed operation. Complete durable result via edt_test_client result operation_id. Perform ONE semantic TestClient action by element name: input text, choose_value from selection, command, tab, row criteria, check/uncheck. Requires exact expected_window from observation; checked in worker before dispatch. Returns job_id; poll edt_operation_status, then re-read edt_form_state to verify business result. No coordinate/keyboard/clipboard actions. Same key protects retries; unknown outcome must be investigated.";}
 public String getParameterSchema(){return """
{"type":"object","additionalProperties":false,"required":["action","expected_window","idempotency_key"],"properties":{"transport":{"enum":["vanessa","testclient"],"default":"vanessa"},"client_id":{"type":"string"},"snapshot_id":{"type":"string"},"expected_form":{"type":"string"},"navigation_link":{"type":"string","maxLength":2048},"expect":{"type":"object","additionalProperties":false,"properties":{"window":{"type":"string"},"fields":{"type":"object","maxProperties":16,"additionalProperties":{"type":"string"}}}},"steps":{"type":"array","minItems":1,"maxItems":16,"items":{"type":"object","additionalProperties":false,"required":["action","expected_window"],"properties":{"action":{"enum":["open","close","input","command"]},"expected_window":{"type":"string"},"expected_form":{"type":"string"},"navigation_link":{"type":"string","maxLength":2048},"element":{"type":"string"},"value":{"type":"string","maxLength":4096},"expect":{"type":"object","additionalProperties":false,"properties":{"window":{"type":"string"},"fields":{"type":"object","maxProperties":16,"additionalProperties":{"type":"string"}}}}}}},"endpoint":{"type":"string"},"client_binding":{"type":"object"},"action":{"enum":["input","choose_value","command","tab","row","check","uncheck","open","close","batch"]},"expected_window":{"type":"string"},"idempotency_key":{"type":"string","maxLength":200},"element":{"type":"string"},"table":{"type":"string"},"value":{"type":"string","maxLength":4096},"row_criteria":{"type":"string"}}}
""";}
 protected CompletableFuture<ToolResult> doExecute(ToolParameters p){return CompletableFuture.supplyAsync(()->{try{if("testclient".equals(p.getRaw().get("transport")))return ToolResult.success(new Gson().toJson(new com.codepilot1c.core.edt.development.DirectTestClientService().act(p.getRaw())));var args=new java.util.LinkedHashMap<String,Object>(p.getRaw());args.remove("transport");var service=RuntimeFormService.workspace();return ToolResult.success(new Gson().toJson(service.act(args)));}catch(Exception e){return ToolResult.failure("edt_form_action: "+e.getMessage());}});}
}
